// Non-atomic read-modify-write on a SharedArrayBuffer -> lost updates.
import { Worker, isMainThread, parentPort, workerData } from 'node:worker_threads';
import { test } from 'node:test';
import assert from 'node:assert/strict';

const WORKERS = 4;
const ITERS = 500_000;

function widenWindow(x) {
  // Dummy local computation between the read and the write so the
  // read-modify-write window is wide enough that the race fires reliably.
  let sink = 0;
  for (let i = 0; i < 50; i++) sink += Math.sqrt(x + i);
  return sink > 0 ? 1 : 0;
}

function runWorkers(file) {
  return new Promise((resolve, reject) => {
    const sab = new SharedArrayBuffer(Int32Array.BYTES_PER_ELEMENT);
    new Int32Array(sab)[0] = 0;
    let done = 0;
    for (let i = 0; i < WORKERS; i++) {
      new Worker(file, { workerData: sab })
        .on('message', () => { if (++done === WORKERS) resolve(new Int32Array(sab)[0]); })
        .on('error', reject);
    }
  });
}

if (!isMainThread) {
  const arr = new Int32Array(workerData);
  for (let i = 0; i < ITERS; i++) {
    const v = arr[0];      // read
    widenWindow(v);        // widen race window
    arr[0] = v + 1;        // write (lost updates happen here)
  }
  parentPort.postMessage('done');
} else {
  test('racy increment loses updates (final < 2,000,000)', { timeout: 30_000 }, async () => {
    const final = await runWorkers(new URL(import.meta.url).pathname);
    console.log(`racy final value: ${final}`);
    assert.ok(final < WORKERS * ITERS, `expected lost updates, got ${final}`);
  });
}

