// Same workload but with Atomics.add -> no lost updates.
import { Worker, isMainThread, parentPort, workerData } from 'node:worker_threads';
import { test } from 'node:test';
import assert from 'node:assert/strict';

const WORKERS = 4;
const ITERS = 500_000;

function runWorkers(file) {
  return new Promise((resolve, reject) => {
    const sab = new SharedArrayBuffer(Int32Array.BYTES_PER_ELEMENT);
    new Int32Array(sab)[0] = 0;
    let done = 0;
    for (let i = 0; i < WORKERS; i++) {
      new Worker(file, { workerData: sab })
        .on('message', () => { if (++done === WORKERS) resolve(Atomics.load(new Int32Array(sab), 0)); })
        .on('error', reject);
    }
  });
}

if (!isMainThread) {
  const arr = new Int32Array(workerData);
  for (let i = 0; i < ITERS; i++) {
    Atomics.add(arr, 0, 1);
  }
  parentPort.postMessage('done');
} else {
  test('Atomics.add yields exactly 2,000,000', { timeout: 30_000 }, async () => {
    const final = await runWorkers(new URL(import.meta.url).pathname);
    console.log(`atomic final value: ${final}`);
    assert.equal(final, WORKERS * ITERS);
  });
}

